          en: 'First U.S. state known for colonial history, Dover, and Atlantic coast',
          ru: 'Первый штат США, известный колониальной историей, Довером и атлантическим побережьем',
          yakut:
              'США бастакы штата, колониальнай историата, Довер куората уонна Атлантика кытыыта',
        );
      case 'usa/georgia_us':
        return _select(
          en: 'Southeastern U.S. state known for Atlanta, civil rights history, and film industry',
          ru: 'Юго-восточный штат США, известный Атлантой, историей гражданских прав и киноиндустрией',
          yakut:
              'Сотугу-илиннээҕи США штата, Атланта куората, гражданскай кыах историата уонна кино индустрията',
        );
      default:
        return region;
    }
  }

